transition: all 0.2s linear;

/* Hover State */
:hover {
    background-color: #ea580c;  /* Darker orange */
    transform: translateY(-1px); /* Lifts slightly */
    box-shadow: 0 10px 15px -3px rgba(249, 115, 22, 0.2);
}

/* Active (Click) State */
:active {
    transform: scale(0.98);     /* Shrinks slightly when clicked */
}
